using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
namespace Staff.Shared.Editor {
[InitializeOnLoad] public static class SurfaceRepairVerification {
 const string W="Library/SurfaceRepair/",K="Staff.SurfaceVerify";static double wait;static int stage;
 static SurfaceRepairVerification(){EditorApplication.update+=Poll;}
 static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;
 if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(W+"verify.request")){File.Delete(W+"verify.request");try{Capture(SceneTravel.City,new Vector3(4,7,-23),new Vector3(0,0,-8),"crossroad.png");Capture(SceneTravel.Subway,new Vector3(3.9f,1.4f,10),new Vector3(4.95f,0,30),"platform.png");File.WriteAllText(W+"play.txt","");SessionState.SetBool(K,true);EditorApplication.isPlaying=true;}catch(Exception e){File.WriteAllText(W+"verify-error.txt",e.ToString());}return;}
 if(!SessionState.GetBool(K,false)||!EditorApplication.isPlaying)return;if(wait==0){wait=EditorApplication.timeSinceStartup;return;}if(EditorApplication.timeSinceStartup-wait<3||SceneTravel.IsLoading)return;
 try{if(stage==0){Check(SceneTravel.Switch(SceneTravel.Subway),"Load city requested");stage++;}else if(stage==1){Check(SceneManager.GetActiveScene().path==SceneTravel.City,"City loaded");Check(UnityEngine.Object.FindFirstObjectByType<SharedGameplay>()!=null,"City common gameplay loaded");Check(SceneTravel.Switch(SceneTravel.City),"Load subway requested");stage++;}else if(stage==2){Check(SceneManager.GetActiveScene().path==SceneTravel.Subway,"Subway loaded");Check(UnityEngine.Object.FindFirstObjectByType<SharedGameplay>()!=null,"Subway common gameplay loaded");Check(SceneTravel.Switch(SceneTravel.Subway),"Return city requested");stage++;}else {Check(SceneManager.GetActiveScene().path==SceneTravel.City,"Round trip completed");Finish();}wait=EditorApplication.timeSinceStartup;}catch(Exception e){File.AppendAllText(W+"play.txt","FAIL "+e);Finish();}
 }
 static void Finish(){SessionState.SetBool(K,false);EditorApplication.isPlaying=false;stage=0;wait=0;}
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);File.AppendAllText(W+"play.txt","PASS "+text+"\n");}
 static void Capture(string path,Vector3 position,Vector3 target,string filename){var scene=SceneManager.GetSceneByPath(path);bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Additive);var obj=new GameObject("Surface verification camera");SceneManager.MoveGameObjectToScene(obj,scene);var cam=obj.AddComponent<Camera>();var reference=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>()).FirstOrDefault(c=>c!=cam);if(reference)cam.CopyFrom(reference);cam.enabled=false;cam.targetTexture=null;cam.overrideSceneCullingMask=EditorSceneManager.GetSceneCullingMask(scene);cam.transform.position=position;cam.transform.LookAt(target);cam.fieldOfView=60;var rt=new RenderTexture(1100,700,24);var prior=RenderTexture.active;Texture2D image=null;try{cam.targetTexture=rt;Staff.Rendering.StaffCameraCapture.Render(cam);RenderTexture.active=rt;image=new Texture2D(1100,700,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1100,700),0,0);image.Apply();File.WriteAllBytes(W+filename,image.EncodeToPNG());}finally{RenderTexture.active=prior;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(obj);UnityEngine.Object.DestroyImmediate(rt);if(image)UnityEngine.Object.DestroyImmediate(image);if(opened)EditorSceneManager.CloseScene(scene,true);}}
}
}
